use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdecltrait! {
# [doc = " We define various kinds of latches, which are all a primitive signaling"] # [doc = " mechanism. A latch starts as false. Eventually someone calls `set()` and"] # [doc = " it becomes true. You can test if it has been set by calling `probe()`."] # [doc = ""] # [doc = " Some kinds of latches, but not all, support a `wait()` operation"] # [doc = " that will wait until the latch is set, blocking efficiently. That"] # [doc = " is not part of the trait since it is not possibly to do with all"] # [doc = " latches."] # [doc = ""] # [doc = " The intention is that `set()` is called once, but `probe()` may be"] # [doc = " called any number of times. Once `probe()` returns true, the memory"] # [doc = " effects that occurred before `set()` become visible."] # [doc = ""] # [doc = " It'd probably be better to refactor the API into two paired types,"] # [doc = " but that's a bit of work, and this is not a public API."] # [doc = ""] # [doc = " ## Memory ordering"] # [doc = ""] # [doc = " Latches need to guarantee two things:"] # [doc = ""] # [doc = " - Once `probe()` returns true, all memory effects from the `set()`"] # [doc = "   are visible (in other words, the set should synchronize-with"] # [doc = "   the probe)."] # [doc = " - Once `set()` occurs, the next `probe()` *will* observe it. This"] # [doc = "   typically requires a seq-cst ordering. See [the \"tickle-then-get-sleepy\" scenario in the sleep"] # [doc = "   README](/src/sleep/README.md#tickle-then-get-sleepy) for details."] pub (super) trait Latch { # [doc = " Set the latch, signalling others."] # [doc = ""] # [doc = " # WARNING"] # [doc = ""] # [doc = " Setting a latch triggers other threads to wake up and (in some"] # [doc = " cases) complete. This may, in turn, cause memory to be"] # [doc = " deallocated and so forth. One must be very careful about this,"] # [doc = " and it's typically better to read all the fields you will need"] # [doc = " to access *before* a latch is set!"] # [doc = ""] # [doc = " This function operates on `*const Self` instead of `&self` to allow it"] # [doc = " to become dangling during this call. The caller must ensure that the"] # [doc = " pointer is valid upon entry, and not invalidated during the call by any"] # [doc = " actions other than `set` itself."] unsafe fn set (this : * const Self) ; }
}